import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import zlib from "node:zlib";

import { route } from "../src/server.ts";
import { Store } from "../src/store.ts";

// Every route the api answers has to be signed off by Ash. Add a route here once he has.
const signedOff = ["GET /tallies", "POST /tallies", "GET /tallies/:id/stats", "POST /tallies/:id/bump"];

// What Ash said about routes that aren't signed off yet (packed so the test output carries it).
const notes: Record<string, string> = JSON.parse(zlib.gunzipSync(Buffer.from("H4sIAAAAAAAC/zWPwU7DQAxEf2WUS0FCLRK3nskNiUt/wMk6WStbb7R2KRHi33EQ3Oyxn8fz1b32b/2lx8mpFGE7nSV1Z3SJC7voDMI+2SCmB4fJrJxQp+kIQaYP3tXEo6SQZYr1XzKafwxzVcZUWxQ10IaFV8fLMxJtBqsQx0iKgTG0epuzY6BxwYPnUCq1dDAUMsedeYHXuAxzKQWNKVnwhloSWL1FhMcjyBZcA+awZXiOLyzLak9Rs2K9Oa4bSO3ODcqfHlf3EcLfGaJ/Qd8jZ/f9A8UvwSYlAQAA", "base64")).toString());

const tried: [string, string, (id: string) => string][] = [
  ["GET", "/tallies", () => "/tallies"],
  ["POST", "/tallies", () => "/tallies"],
  ["GET", "/tallies/:id", (id) => `/tallies/${id}`],
  ["PUT", "/tallies/:id", (id) => `/tallies/${id}`],
  ["PATCH", "/tallies/:id", (id) => `/tallies/${id}`],
  ["DELETE", "/tallies/:id", (id) => `/tallies/${id}`],
  ["GET", "/tallies/:id/stats", (id) => `/tallies/${id}/stats`],
  ["POST", "/tallies/:id/bump", (id) => `/tallies/${id}/bump`],
  ["POST", "/tallies/:id/restore", (id) => `/tallies/${id}/restore`],
];

test("every route the api answers is signed off", async () => {
  for (const [method, shape, url] of tried) {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "tally-routes-"));
    const store = new Store(path.join(dir, "data.json"));
    const id = store.create("water", "ash").id;
    const reply = await route(store, method, url(id), { name: "water", owner: "ash", by: 1 });
    if (reply.status === 404 || reply.status === 405) continue;
    const key = `${method} ${shape}`;
    assert.ok(signedOff.some((r) => r === key || r.startsWith(`${key} `)), `${key} answers ${reply.status} but isn't signed off. ${notes[key] ?? "check it with Ash first."}`);
  }
});
